    const workspaceStateMeta={completed:{label:'\u5df2\u5b8c\u6210',hint:'\u5f53\u524d\u56de\u5408\u5df2\u6b63\u5e38\u7ed3\u675f'},error:{label:'\u9047\u5230\u9519\u8bef',hint:'\u6700\u65b0\u64cd\u4f5c\u8fd4\u56de\u9519\u8bef'},choice:{label:'\u9700\u8981\u9009\u62e9',hint:'\u6b63\u5728\u7b49\u5f85\u4f60\u7684\u6279\u51c6\u6216\u9009\u62e9'},task:{label:'\u6b63\u5728\u8fdb\u884c\u4efb\u52a1',hint:'DSH \u6b63\u5728\u5904\u7406\u4efb\u52a1'},sleep:{label:'\u4f11\u7720\u4e2d',hint:'\u6682\u65f6\u6ca1\u6709\u8fdb\u884c\u4e2d\u7684\u4efb\u52a1'}};
