    function countdownNext(item){const [y,m,d]=item.date.split('-').map(Number);if(!m||!d)return null;const today=new Date();today.setHours(0,0,0,0);const thisYear=new Date(today.getFullYear(),m-1,d);if(!item.yearly)return thisYear<today?null:thisYear;let next=thisYear;if(next<today){next=new Date(next);next.setFullYear(next.getFullYear()+1)}return next}
