    $('#countdown-form').onsubmit=e=>{e.preventDefault();const name=$('#countdown-name').value.trim().slice(0,16),date=$('#countdown-date').value;if(!name||!/^\d{4}-\d{2}-\d{2}$/.test(date)){notice('请填写名称和日期');return}const list=countdowns();if(list.some(i=>i.name===name&&i.date===date)){notice('这个纪念日已经存在');return}list.push({name,date,yearly:$('#countdown-yearly').checked});saveCountdowns(list);$('#countdown-name').value='';$('#countdown-date').value='';renderCountdownSettings();renderCountdowns();notice('纪念日已添加')};

